import java.io.*;import java.util.*;class Result {public static int sherlockAndAnagrams(String s) {Map<String, Integer> map = new HashMap<>();int n = s.length();for (int i = 0; i < n; i++) {for (int j = i + 1; j <= n; j++) {String sub = s.substring(i, j);char[] chars = sub.toCharArray();Arrays.sort(chars);String key = new String(chars);map.put(key, map.getOrDefault(key, 0) + 1);}}int count = 0;for (int val : map.values()) {if (val > 1) {count += (val * (val - 1)) / 2;}}return count;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));String output = System.getenv("OUTPUT_PATH");BufferedWriter bufferedWriter = output != null ? new BufferedWriter(new FileWriter(output)) : new BufferedWriter(new OutputStreamWriter(System.out));String line = bufferedReader.readLine();if (line != null) {int q = Integer.parseInt(line.trim());for (int i = 0; i < q; i++) {String s = bufferedReader.readLine();int result = Result.sherlockAndAnagrams(s);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();}}bufferedReader.close();bufferedWriter.close();}}